### `align.go`

```go
// Package align implements global pairwise alignment with affine gaps
// (Gotoh), both as a full O(n*m) dynamic program and as a banded,
// X-drop-pruned variant that reports clipping explicitly.
package align

import (
	"errors"
	"fmt"
	"strings"
)

// negInf is a sentinel for "unreachable / pruned". It is far enough below
// any real score that it can never win a max, yet adding gap penalties to
// it will not overflow on realistic inputs.
const negInf = -1 << 30

// Config holds the scoring and pruning parameters.
//
// A gap of length k costs GapOpen + k*GapExtend (GapOpen is the opening
// penalty, GapExtend is charged for every gap symbol, including the first).
// Band is the half-width of the band around the main diagonal:
// a cell (i,j) is retained iff |i-j| <= Band. Band < 0 means full DP.
// XDrop <= 0 disables X-drop pruning.
//
// Verify, when true, enables an exact optimality certificate: the banded
// score is compared against a score-only full O(n*m) DP. A non-sentinel
// result is then guaranteed to equal the unbanded Gotoh optimum. With
// Verify=false the detector falls back to a conservative band-edge
// heuristic (faster, but no longer sound).
type Config struct {
	Match     int
	Mismatch  int
	GapOpen   int
	GapExtend int
	Band      int
	XDrop     int
	Verify    bool
}

// DefaultConfig returns a sane, tie-poor scoring scheme with exact
// verification enabled.
func DefaultConfig() Config {
	return Config{Match: 2, Mismatch: -1, GapOpen: -3, GapExtend: -1, Band: -1, XDrop: 0, Verify: true}
}

// ErrClipped is the explicit sentinel returned whenever the band or the
// X-drop pruning may have removed the true optimum. Callers must never
// treat a clipped alignment as a valid score.
var ErrClipped = errors.New("alignment clipped: band or X-drop removed the optimal path")

// State is the affine-gap state of a DP cell.
type State uint8

const (
	StateM State = iota // last column is a (mis)match
	StateX              // last column consumes a, gap in b (CIGAR 'D')
	StateY              // last column consumes b, gap in a (CIGAR 'I')
)

func (s State) String() string {
	switch s {
	case StateM:
		return "M"
	case StateX:
		return "X"
	case StateY:
		return "Y"
	}
	return "?"
}

// Cell records one visited cell of a traceback path.
type Cell struct {
	I, J int
	St   State
}

// Result is a successful (unclipped) alignment.
type Result struct {
	Score int
	CIGAR string
	Path  []Cell
}

type dpResult struct {
	score      int
	cigar      string
	path       []Cell
	xdropFired bool
}

func inBand(i, j, band int) bool {
	if band < 0 {
		return true
	}
	d := i - j
	if d < 0 {
		d = -d
	}
	return d <= band
}

// gotoh is the single core routine. band < 0 means full DP; xdrop <= 0
// disables pruning. It returns a dpResult; score == negInf means no path
// existed inside the band.
func gotoh(a, b string, cfg Config, band, xdrop int) dpResult {
	n, m := len(a), len(b)

	// We retain the whole (n+1)x(m+1) grid but only *fill* the band.
	// Unfilled cells stay negInf, which is exactly the value of an
	// out-of-band predecessor. This is the key to correct traceback
	// across band edges: lookups never go out of range and never read
	// stale/zero values.
	M := make([][]int, n+1)
	X := make([][]int, n+1)
	Y := make([][]int, n+1)
	pM := make([][]int8, n+1)
	pX := make([][]int8, n+1)
	pY := make([][]int8, n+1)
	for i := 0; i <= n; i++ {
		M[i] = make([]int, m+1)
		X[i] = make([]int, m+1)
		Y[i] = make([]int, m+1)
		pM[i] = make([]int8, m+1)
		pX[i] = make([]int8, m+1)
		pY[i] = make([]int8, m+1)
		for j := 0; j <= m; j++ {
			M[i][j], X[i][j], Y[i][j] = negInf, negInf, negInf
			pM[i][j], pX[i][j], pY[i][j] = -1, -1, -1
		}
	}
	M[0][0] = 0

	best := 0
	xdropFired := false

	for i := 0; i <= n; i++ {
		for j := 0; j <= m; j++ {
			if i == 0 && j == 0 {
				continue
			}
			if !inBand(i, j, band) {
				continue
			}

			// ---- M: (i-1,j-1) -> (i,j), consumes both ----
			if i > 0 && j > 0 {
				bm, sm := negInf, int8(-1)
				if M[i-1][j-1] > bm {
					bm, sm = M[i-1][j-1], 0
				}
				if X[i-1][j-1] > bm {
					bm, sm = X[i-1][j-1], 1
				}
				if Y[i-1][j-1] > bm {
					bm, sm = Y[i-1][j-1], 2
				}
				if bm > negInf {
					sc := cfg.Mismatch
					if a[i-1] == b[j-1] {
						sc = cfg.Match
					}
					M[i][j] = bm + sc
					pM[i][j] = sm
				}
			}

			// ---- X: (i-1,j) -> (i,j), consumes a, gap in b ----
			// Each predecessor gets its own gap penalty, then we maximise.
			// Tie order: extend (X), then open from M, then open from Y.
			if i > 0 {
				bx, sx := negInf, int8(-1)
				if X[i-1][j] > negInf {
					if c := X[i-1][j] + cfg.GapExtend; c > bx {
						bx, sx = c, 1
					}
				}
				if M[i-1][j] > negInf {
					if c := M[i-1][j] + cfg.GapOpen + cfg.GapExtend; c > bx {
						bx, sx = c, 0
					}
				}
				if Y[i-1][j] > negInf {
					if c := Y[i-1][j] + cfg.GapOpen + cfg.GapExtend; c > bx {
						bx, sx = c, 2
					}
				}
				if sx != -1 {
					X[i][j] = bx
					pX[i][j] = sx
				}
			}

			// ---- Y: (i,j-1) -> (i,j), consumes b, gap in a ----
			// Each predecessor gets its own gap penalty.
			// Tie order: extend (Y), then open from M, then open from X.
			if j > 0 {
				by, sy := negInf, int8(-1)
				if Y[i][j-1] > negInf {
					if c := Y[i][j-1] + cfg.GapExtend; c > by {
						by, sy = c, 2
					}
				}
				if M[i][j-1] > negInf {
					if c := M[i][j-1] + cfg.GapOpen + cfg.GapExtend; c > by {
						by, sy = c, 0
					}
				}
				if X[i][j-1] > negInf {
					if c := X[i][j-1] + cfg.GapOpen + cfg.GapExtend; c > by {
						by, sy = c, 1
					}
				}
				if sy != -1 {
					Y[i][j] = by
					pY[i][j] = sy
				}
			}

			// ---- X-drop pruning ----
			cur := M[i][j]
			if X[i][j] > cur {
				cur = X[i][j]
			}
			if Y[i][j] > cur {
				cur = Y[i][j]
			}
			if cur > best {
				best = cur
			}
			if xdrop > 0 {
				thr := best - xdrop
				if M[i][j] < thr {
					M[i][j], pM[i][j] = negInf, -1
					xdropFired = true
				}
				if X[i][j] < thr {
					X[i][j], pX[i][j] = negInf, -1
					xdropFired = true
				}
				if Y[i][j] < thr {
					Y[i][j], pY[i][j] = negInf, -1
					xdropFired = true
				}
			}
		}
	}

	score := M[n][m]
	st := StateM
	if X[n][m] > score {
		score, st = X[n][m], StateX
	}
	if Y[n][m] > score {
		score, st = Y[n][m], StateY
	}
	res := dpResult{score: score, xdropFired: xdropFired}
	if score <= negInf {
		return res
	}

	// ---- traceback ----
	i, j := n, m
	ops := make([]byte, 0, n+m)
	path := make([]Cell, 0, n+m)
	for i > 0 || j > 0 {
		path = append(path, Cell{I: i, J: j, St: st})
		switch st {
		case StateM:
			st = State(pM[i][j])
			ops = append(ops, 'M')
			i--
			j--
		case StateX:
			st = State(pX[i][j])
			ops = append(ops, 'D')
			i--
		case StateY:
			st = State(pY[i][j])
			ops = append(ops, 'I')
			j--
		default:
			// Should be unreachable: every reachable state records a
			// predecessor. A -1 here would mean a corrupted matrix.
			res.score = negInf
			return res
		}
	}
	// ops is reversed; reverse it.
	for l, r := 0, len(ops)-1; l < r; l, r = l+1, r-1 {
		ops[l], ops[r] = ops[r], ops[l]
	}
	res.cigar = compress(ops)
	res.path = path
	return res
}

func compress(ops []byte) string {
	if len(ops) == 0 {
		return ""
	}
	var sb strings.Builder
	run := 1
	for k := 1; k <= len(ops); k++ {
		if k < len(ops) && ops[k] == ops[k-1] {
			run++
			continue
		}
		fmt.Fprintf(&sb, "%d%c", run, ops[k-1])
		run = 1
	}
	return sb.String()
}

// AlignFull runs the exact, unbanded O(n*m) Gotoh algorithm.
func AlignFull(a, b string, cfg Config) (Result, error) {
	r := gotoh(a, b, cfg, -1, 0)
	if r.score <= negInf {
		return Result{}, fmt.Errorf("full alignment failed (unreachable)")
	}
	return Result{Score: r.score, CIGAR: r.cigar, Path: r.path}, nil
}

// MaxDiag returns the largest |i-j| over a path.
func MaxDiag(path []Cell) int {
	md := 0
	for _, c := range path {
		d := c.I - c.J
		if d < 0 {
			d = -d
		}
		if d > md {
			md = d
		}
	}
	return md
}

// fullScore computes the exact unbanded Gotoh score with O(m) memory. It is
// the optimality certificate used by AlignBanded when Verify is set.
func fullScore(a, b string, cfg Config) int {
	n, m := len(a), len(b)
	if n == 0 && m == 0 {
		return 0
	}
	// Row 0.
	Mp := make([]int, m+1)
	Xp := make([]int, m+1)
	Yp := make([]int, m+1)
	Mc := make([]int, m+1)
	Xc := make([]int, m+1)
	Yc := make([]int, m+1)
	for j := 0; j <= m; j++ {
		Mp[j], Xp[j], Yp[j] = negInf, negInf, negInf
	}
	Mp[0] = 0
	for j := 1; j <= m; j++ {
		by := negInf
		if Yp[j-1] > negInf {
			by = Yp[j-1] + cfg.GapExtend
		}
		if Mp[j-1] > negInf {
			if c := Mp[j-1] + cfg.GapOpen + cfg.GapExtend; c > by {
				by = c
			}
		}
		if Xp[j-1] > negInf {
			if c := Xp[j-1] + cfg.GapOpen + cfg.GapExtend; c > by {
				by = c
			}
		}
		Yp[j] = by
	}

	for i := 1; i <= n; i++ {
		Mc[0], Yc[0] = negInf, negInf
		bx := negInf
		if Xp[0] > negInf {
			bx = Xp[0] + cfg.GapExtend
		}
		if Mp[0] > negInf {
			if c := Mp[0] + cfg.GapOpen + cfg.GapExtend; c > bx {
				bx = c
			}
		}
		if Yp[0] > negInf {
			if c := Yp[0] + cfg.GapOpen + cfg.GapExtend; c > bx {
				bx = c
			}
		}
		Xc[0] = bx

		for j := 1; j <= m; j++ {
			// M
			bm := Mp[j-1]
			if Xp[j-1] > bm {
				bm = Xp[j-1]
			}
			if Yp[j-1] > bm {
				bm = Yp[j-1]
			}
			if bm > negInf {
				sc := cfg.Mismatch
				if a[i-1] == b[j-1] {
					sc = cfg.Match
				}
				Mc[j] = bm + sc
			} else {
				Mc[j] = negInf
			}

			// X
			bx := negInf
			if Xp[j] > negInf {
				bx = Xp[j] + cfg.GapExtend
			}
			if Mp[j] > negInf {
				if c := Mp[j] + cfg.GapOpen + cfg.GapExtend; c > bx {
					bx = c
				}
			}
			if Yp[j] > negInf {
				if c := Yp[j] + cfg.GapOpen + cfg.GapExtend; c > bx {
					bx = c
				}
			}
			Xc[j] = bx

			// Y
			by := negInf
			if Yc[j-1] > negInf {
				by = Yc[j-1] + cfg.GapExtend
			}
			if Mc[j-1] > negInf {
				if c := Mc[j-1] + cfg.GapOpen + cfg.GapExtend; c > by {
					by = c
				}
			}
			if Xc[j-1] > negInf {
				if c := Xc[j-1] + cfg.GapOpen + cfg.GapExtend; c > by {
					by = c
				}
			}
			Yc[j] = by
		}
		Mp, Mc = Mc, Mp
		Xp, Xc = Xc, Xp
		Yp, Yc = Yc, Yp
	}

	best := Mp[m]
	if Xp[m] > best {
		best = Xp[m]
	}
	if Yp[m] > best {
		best = Yp[m]
	}
	return best
}

// AlignBanded runs the banded, X-drop-pruned Gotoh algorithm.
//
// If the band and X-drop did not remove the optimum it returns the exact
// optimum score and the optimal CIGAR (identical to AlignFull). Otherwise
// it returns an error wrapping ErrClipped. It never returns a silently
// wrong score: when cfg.Verify is set, an exact score-only full DP is used
// to prove optimality before any result is returned.
func AlignBanded(a, b string, cfg Config) (Result, error) {
	band := cfg.Band

	// Candidate from the banded DP (unpruned): the score we must certify.
	base := gotoh(a, b, cfg, band, 0)
	if base.score <= negInf {
		return Result{}, fmt.Errorf("%w: no path exists inside the band", ErrClipped)
	}

	// Optimality certificate.
	if cfg.Verify {
		want := fullScore(a, b, cfg)
		if base.score != want {
			return Result{}, fmt.Errorf(
				"%w: band clipped the optimum (banded=%d, full=%d)", ErrClipped, base.score, want)
		}
	} else if band >= 0 {
		// Conservative (but not sound) heuristic fallback.
		md := MaxDiag(base.path)
		if md >= band {
			return Result{}, fmt.Errorf(
				"%w: optimal path touches band edge (max |i-j|=%d, band=%d)",
				ErrClipped, md, band)
		}
	}

	// X-drop: pruning only ever removes paths. If the pruned and unpruned
	// banded optima differ, the pruned run cannot be trusted.
	if cfg.XDrop > 0 {
		pruned := gotoh(a, b, cfg, band, cfg.XDrop)
		if pruned.score != base.score {
			return Result{}, fmt.Errorf(
				"%w: X-drop pruned the optimum (pruned=%d, unpruned=%d)",
				ErrClipped, pruned.score, base.score)
		}
	}

	return Result{Score: base.score, CIGAR: base.cigar, Path: base.path}, nil
}

// ScoreCIGAR independently re-scores a CIGAR against a and b using the same
// affine-gap model, and verifies that it consumes both sequences exactly.
func ScoreCIGAR(a, b, cigar string, cfg Config) (int, error) {
	i, j, score := 0, 0, 0
	idx := 0
	for idx < len(cigar) {
		num := 0
		digits := 0
		for idx < len(cigar) && cigar[idx] >= '0' && cigar[idx] <= '9' {
			num = num*10 + int(cigar[idx]-'0')
			idx++
			digits++
		}
		if digits == 0 || idx >= len(cigar) {
			return 0, fmt.Errorf("malformed CIGAR %q", cigar)
		}
		if num == 0 {
			return 0, fmt.Errorf("zero-length CIGAR op in %q", cigar)
		}
		op := cigar[idx]
		idx++
		switch op {
		case 'M':
			if i+num > len(a) || j+num > len(b) {
				return 0, fmt.Errorf("CIGAR %q overruns sequences", cigar)
			}
			for k := 0; k < num; k++ {
				if a[i+k] == b[j+k] {
					score += cfg.Match
				} else {
					score += cfg.Mismatch
				}
			}
			i += num
			j += num
		case 'I':
			if j+num > len(b) {
				return 0, fmt.Errorf("CIGAR %q overruns b", cigar)
			}
			score += cfg.GapOpen + num*cfg.GapExtend
			j += num
		case 'D':
			if i+num > len(a) {
				return 0, fmt.Errorf("CIGAR %q overruns a", cigar)
			}
			score += cfg.GapOpen + num*cfg.GapExtend
			i += num
		default:
			return 0, fmt.Errorf("unknown CIGAR op %q in %q", op, cigar)
		}
	}
	if i != len(a) || j != len(b) {
		return 0, fmt.Errorf("CIGAR %q does not consume the sequences exactly", cigar)
	}
	return score, nil
}
