### `align_test.go`

```go
package align

import (
	"errors"
	"math/rand"
	"strings"
	"testing"
)

func randSeq(r *rand.Rand, n int, alpha string) string {
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteByte(alpha[r.Intn(len(alpha))])
	}
	return sb.String()
}

// TestFullBasic checks the full aligner on hand-computable cases.
func TestFullBasic(t *testing.T) {
	cfg := DefaultConfig() // match=2 mismatch=-1 go=-3 ge=-1

