// TestDifferentialExactness is the core proof: whenever the full O(n*m)
// optimum stays strictly inside the band, the banded run must return the
// exact same score AND the exact same CIGAR.
func TestDifferentialExactness(t *testing.T) {
	r := rand.New(rand.NewSource(20240923))
	alpha := "ACGT"
	cfg := DefaultConfig()
	cfg.XDrop = 0 // isolate band exactness

	checked, skipped := 0, 0
	for iter := 0; iter < 4000; iter++ {
		na := 1 + r.Intn(40)
		nb := 1 + r.Intn(40)
		a := randSeq(r, na, alpha)
		b := randSeq(r, nb, alpha)

		full, err := AlignFull(a, b, cfg)
		if err != nil {
			t.Fatal(err)
		}
		md := MaxDiag(full.Path)

		// Try a band strictly larger than the excursion of the true optimum.
		band := md + 1 + r.Intn(4)
		if band > na+nb+2 {
			continue
		}
		cfg.Band = band

		banded, err := AlignBanded(a, b, cfg)
		if err != nil {
			if errors.Is(err, ErrClipped) {
				// The true optimum is strictly interior, so the well-behaved
				// certificate must not fire. This is a real defect.
				t.Fatalf("false clip: a=%q b=%q band=%d fullPathMaxDiag=%d: %v", a, b, band, md, err)
			}
			t.Fatal(err)
		}
		if banded.Score != full.Score {
			t.Fatalf("score mismatch a=%q b=%q band=%d: banded=%d full=%d", a, b, band, banded.Score, full.Score)
		}
		if banded.CIGAR != full.CIGAR {
			t.Fatalf("CIGAR mismatch a=%q b=%q band=%d:\n banded=%s\n full  =%s", a, b, band, banded.CIGAR, full.CIGAR)
		}
		// Independent rescoring of the banded CIGAR.
		sc, err := ScoreCIGAR(a, b, banded.CIGAR, cfg)
		if err != nil {
			t.Fatal(err)
		}
		if sc != full.Score {
			t.Fatalf("banded CIGAR rescores to %d, full optimum %d", sc, full.Score)
		}
		checked++
	}
	if checked < 500 {
		t.Fatalf("differential test only checked %d cases", checked)
	}
	t.Logf("differential exactness: %d in-band cases verified, %d skipped", checked, skipped)
}

// TestBandTooSmallIsSentinel shows a 1% band is reported as insufficient when
// the optimum leaves the band.
func TestBandTooSmallIsSentinel(t *testing.T) {
	cfg := DefaultConfig()
	// A long block swap forces the optimal path to |i-j| = 200.
	a := strings.Repeat("A", 200) + strings.Repeat("C", 200)
	b := strings.Repeat("C", 200) + strings.Repeat("A", 200)
	cfg.Band = (len(a) + len(b)) / 200 // ~1% of 400 = 4
	if cfg.Band < 1 {
		cfg.Band = 1
	}

	full, err := AlignFull(a, b, cfg)
	if err != nil {
		t.Fatal(err)
	}
	if md := MaxDiag(full.Path); md <= cfg.Band {
		t.Fatalf("test construction invalid: full path max|i-j|=%d not outside band %d", md, cfg.Band)
	}

	_, err = AlignBanded(a, b, cfg)
	if !errors.Is(err, ErrClipped) {
		t.Fatalf("expected ErrClipped for 1%% band, got err=%v", err)
	}
	t.Logf("correctly clipped at band=%d (optimum reaches |i-j|=%d): %v", cfg.Band, MaxDiag(full.Path), err)
}

// TestXDropClipped verifies X-drop pruning that removes the optimum is
// reported, while a large X-drop budget leaves the answer exact.
func TestXDropClipped(t *testing.T) {
	cfg := DefaultConfig()
	cfg.Band = -1 // full width, isolate X-drop
	a := strings.Repeat("A", 10) + strings.Repeat("C", 10) + strings.Repeat("A", 10)
	b := strings.Repeat("A", 10) + strings.Repeat("G", 10) + strings.Repeat("A", 10)

	full, err := AlignFull(a, b, cfg)
	if err != nil {
		t.Fatal(err)
	}

	// Tight X-drop will prune the low-scoring middle of the optimal path.
	cfg.XDrop = 3
	if _, err := AlignBanded(a, b, cfg); !errors.Is(err, ErrClipped) {
		t.Fatalf("tight X-drop should clip, got err=%v", err)
	} else {
		t.Logf("tight X-drop clipped as expected: %v", err)
	}

	// Generous X-drop budget keeps the optimum.
	cfg.XDrop = 10 * cfg.Match
	res, err := AlignBanded(a, b, cfg)
	if err != nil {
		t.Fatalf("generous X-drop should not clip: %v", err)
	}
	if res.Score != full.Score {
		t.Fatalf("generous X-drop score %d, want %d", res.Score, full.Score)
	}
}

// TestBandEdgeTraceback exercises traceback right against the band edge,
// where predecessors fall outside the retained rows. The banded result must
// either exactly match the full optimum (if truly interior) or clip.
func TestBandEdgeTraceback(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	alpha := "ACGT"
	cfg := DefaultConfig()
	for iter := 0; iter < 3000; iter++ {
		a := randSeq(r, 1+r.Intn(30), alpha)
		b := randSeq(r, 1+r.Intn(30), alpha)
		full, err := AlignFull(a, b, cfg)
		if err != nil {
			t.Fatal(err)
		}
		md := MaxDiag(full.Path)
		// Deliberately include bands at and below the true excursion to
		// force edge contacts and out-of-band predecessors.
		for _, band := range []int{1, 2, 3, 5, 8} {
			cfg.Band = band
			res, err := AlignBanded(a, b, cfg)
			if err != nil {
				if !errors.Is(err, ErrClipped) {
					t.Fatalf("unexpected error: %v", err)
				}
				continue
			}
			// If it did not clip, it must agree with the full optimum. This is
			// the exactness property under the band/edge stress test.
			if res.Score != full.Score {
				t.Fatalf("unclipped score %d != full %d (a=%q b=%q band=%d, full excursion %d)", res.Score, full.Score, a, b, band, md)
			}
			if _, err := ScoreCIGAR(a, b, res.CIGAR, cfg); err != nil {
				t.Fatalf("bad CIGAR at band edge: %v", err)
			}
		}
	}
}

